package env_test

import (
	"encoding/json"
	"os"
	"reflect"
	"testing"

	"github.com/MichaelKinsy/PiG/env"
)

// error_classes_cases.json holds Pi's RemoteError (connection.ts:22-34) and SshError (ssh.ts:46-55) on a fixed corpus, generated by
// testdata/generate_error_classes.mjs. Regenerate it from the repository root with:
//
//	node env/testdata/generate_error_classes.mjs > env/testdata/error_classes_cases.json
type errorClassCase struct {
	Name    string `json:"name"`
	Message string `json:"message"`
	Text    string `json:"text"`
	IsError bool   `json:"isError"`
	Cause   bool   `json:"hasCause"`
}

// jsErrorString is Error.prototype.toString.
func jsErrorString(name, message string) string {
	if message == "" {
		return name
	}
	return name + ": " + message
}

func TestErrorClassesMatchPi(t *testing.T) {
	t.Parallel()
	data, err := os.ReadFile("testdata/error_classes_cases.json")
	if err != nil {
		t.Fatal(err)
	}
	var golden struct {
		Remote []struct {
			Fields    env.Json `json:"fields"`
			OutFields env.Json `json:"outFields"`
			Code      string   `json:"code"`
			Path      *string  `json:"path"`
			errorClassCase
		} `json:"remote"`
		Ssh []struct {
			InMessage  string `json:"inMessage"`
			InExitCode *int   `json:"inExitCode"`
			InStderr   string `json:"inStderr"`
			ExitCode   *int   `json:"exitCode"`
			Stderr     string `json:"stderr"`
			errorClassCase
		} `json:"ssh"`
	}
	if err := json.Unmarshal(data, &golden); err != nil {
		t.Fatal(err)
	}
	if len(golden.Remote) == 0 || len(golden.Ssh) == 0 {
		t.Fatal("the golden file is empty; regenerate it with testdata/generate_error_classes.mjs")
	}
	newRemote := env.NewRemoteError
	for _, c := range golden.Remote {
		got := newRemote(c.Fields)
		if got.Name() != c.Name || got.Error() != c.Message || jsErrorString(got.Name(), got.Error()) != c.Text || !c.IsError || c.Cause {
			t.Errorf("NewRemoteError(%v) = %q %q, Pi %q %q", c.Fields, got.Name(), got.Error(), c.Name, c.Message)
		}
		if got.Code != c.Code || !reflect.DeepEqual(got.Path, c.Path) || !reflect.DeepEqual(got.Fields, c.OutFields) {
			t.Errorf("NewRemoteError(%v): code %q path %v fields %v, Pi code %q path %v fields %v", c.Fields, got.Code, got.Path, got.Fields, c.Code, c.Path, c.OutFields)
		}
	}
	for _, c := range golden.Ssh {
		got := env.NewSshError(c.InMessage, c.InExitCode, c.InStderr)
		if got.Name() != c.Name || got.Error() != c.Message || jsErrorString(got.Name(), got.Error()) != c.Text || !c.IsError || c.Cause {
			t.Errorf("NewSshError(%q) = %q %q, Pi %q %q", c.InMessage, got.Name(), got.Error(), c.Name, c.Message)
		}
		if !reflect.DeepEqual(got.ExitCode, c.ExitCode) || got.Stderr != c.Stderr {
			t.Errorf("NewSshError(%q): exit %v stderr %q, Pi exit %v stderr %q", c.InMessage, got.ExitCode, got.Stderr, c.ExitCode, c.Stderr)
		}
	}
}
